INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('home-sheep-home-farmageddon-party-edition', 123322, '2019-10-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7gbc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcj5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Home Sheep Home: Farmageddon Party Edition', 'Join Shaun the Sheep and his friends Timmy and Shirley on this epic adventure journeying through underground caverns, negotiating the busy streets of London and teleporting through outer space all in search of the green, green grass of home. Let''s Ewe This! Overcome the fiendishly challenging puzzles by working as a flock with new multiplayer features, using each sheep’s unique abilities to solve challenges and shove, leap, squeeze and swim through underground tunnels, abandoned mineshafts - and even evade the guards at Buckingham Palace. All new multiplayer Baaa-tle A brand new suite of action-packed, Shaun the Sheep movie themed party games bring some extra-terrestrial chaos to the farm with a visit to the Farmageddon theme park where you can compete with family and friends in a series of madcap fairground games hosted by Shaun’s new alien pal Lu-La, who has crash-landed near Mossy Bottom Farm. Lovingly Lamb-made animation "Brought to you by award winning animation studio Aardman the game features a beautiful hand-painted and traditionally animated art style, spectacular environments and endearing character animation. Reviews for Home Sheep Home 2... “It''s like some sort of adorable vortex you never want to leave...there''s something to be said for a game that goes out of its way to excel at style and quality, and Home Sheep Home 2 definitely has both by the bushel.” 4.7/5 – Jay Is Games “What’s more impressive about this game is how little is reused. Basic puzzle mechanics stay throughout (only by stepping on the button can you open the door) but the…' FROM games WHERE igdb_id = 123322 ON CONFLICT (game_id, language_code) DO NOTHING;
