INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ravon', 'Ravon is a new rhythm game established in 2019 that combines elements of reading, memory, and pattern recognition. With 4 difficulty levels, this game has charts for rhythm gamers of all skill levels. There is either a 3x5 or 4x6 grid of squares, and notes come down in 4 directions that a player has to tap when it reaches the center of a particular square that is indicated with a white outline.' FROM games WHERE igdb_id = 142390 ON CONFLICT (game_id, language_code) DO NOTHING;
