INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Combat VR', 'ファンタジーな世界で自分自身が魔法使いになって、他のプレイヤーと戦う対戦型マルチVRゲームである。 その昔、戦争で人口が激減してしまった世界で生きるために魔法が開拓された。魔法技術が発展していく中、魔法使い達は己が培ってきた能力の優位性を証明する為に競うようになった。' FROM games WHERE igdb_id = 115181 ON CONFLICT (game_id, language_code) DO NOTHING;
