INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'There is No GreenDam', '只是想找一份简单的工作，却没想到惹出这么多麻烦，最终我收到了一个谜一样的测试物——一位少女。那么要从此开启幸福的同居生活了？……不存在的，这仅仅只是大灾变前的预兆！！我与她的故事才刚刚开启……一个临时建成的制作组产出的治愈向Galgame，希望能给你带来小小的感动。' FROM games WHERE igdb_id = 126532 ON CONFLICT (game_id, language_code) DO NOTHING;
