INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dont-wake-the-night', 119252, '2019-05-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1lt0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqtu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Don''t Wake the Night', 'A 2D point-and-click game, Don''t Wake the Night is a visual novel-inspired game based on elements of community, witchcraft, and ancestry. As the player, you navigate the story as the spirit, an entity summoned by a community of witches who are in the middle of handing out judgement, which they leave up to you to decide. Having no memories of the world of the living, you must gather as much information as possible before making your decision. The witches themselves cannot see or hear you — for those who are not given the responsibility of speaking with spirits cannot approach them. Don''t Wake the Night is a collection of honest conversations between individuals belonging to the same community, and the heartache that comes with doubt and brewing tensions.' FROM games WHERE igdb_id = 119252 ON CONFLICT (game_id, language_code) DO NOTHING;
