INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OneBit Adventure', 'OneBit is a casual turn-based roguelike RPG with endless adventure against 8-bit monsters. Adventure as far as you can to find loot, level up your stats, and reach your max potential. Choose from a variety of classes that range in different abilities in this epic turn-based roguelike RPG. Play on-the-go with one hand and save with a tap so you can play anytime! The game''s minimalistic approach is easy on the eyes and allows you to learn very quickly.' FROM games WHERE igdb_id = 125517 ON CONFLICT (game_id, language_code) DO NOTHING;
