INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Driver', 'Build your career as a Truck Driver! Fuel up and cruise through a vast open world in one of the most beautiful machines known to man. Start off as a contractor and work your way up by taking on jobs, earning money and making a name for yourself amongst the local community. Buy your own trucks, get new parts and hurtle down the roads! Do you have what it takes to become a respected Truck Driver?' FROM games WHERE igdb_id = 90387 ON CONFLICT (game_id, language_code) DO NOTHING;
