INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Lady! New Division', '《淑女同萌！-New Division-》是晓WORKS于2014年末发售的校园爱情悬疑作品《淑女同萌！》的外传故事（FAN DISC）。游戏剧情采用了双线叙事模式，以在《淑女同萌！》本篇中人气极高的两位女配角菱吾森和兜山美鸟为主角，讲述了属于她们各自的故事。是一款本篇玩家不可错过的精彩外传。' FROM games WHERE igdb_id = 117215 ON CONFLICT (game_id, language_code) DO NOTHING;
