INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Open World Game: The Open World Game', 'Open World Game: the Open World Game is the purest open world game experience. We broke open world games down to their core so you don''t have to deal with any more gorgeous 3D environments distracting you, stellar voice acting performances drawing you in, or even a prolonged epic Main Quest constantly weighing you down for ignoring it in lieu of collecting every card in that mini game. Just pure unadulterated open world game... game.' FROM games WHERE igdb_id = 130270 ON CONFLICT (game_id, language_code) DO NOTHING;
