INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Equaline', 'Equaline is a "one-stroke calculation puzzle" where you have to connect numbers and symbols with lines to complete a calculation. There is only one correct answer for each combination of nine squares, and the target number increases with each puzzle. It''s a highly competitive action puzzle game.' FROM games WHERE igdb_id = 169591 ON CONFLICT (game_id, language_code) DO NOTHING;
