INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('emma-lost-in-memories', 121380, '2019-08-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26m9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardc0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emma: Lost in Memories', 'Emma is a 2D puzzle platformer that revolves around a potent central mechanic: all the platforms and walls start disappearing when the player touches them. This creates a series of challenges around this idea. Also, the player only needs to focus on jumping and reacting to its environment as he runs automatically. The game is all about overcoming one-screen puzzles with skill and ingenuity. Emma aims to be a simple and enjoyable game that works around the concept of fading away, both mechanically and thematically through delicate storytelling. Emma tackles themes like loss (focused on memory loss) and the acceptance of who you are.' FROM games WHERE igdb_id = 121380 ON CONFLICT (game_id, language_code) DO NOTHING;
