INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deuterium Wars', 'Multiplayer cross-platform 2D shooter that combines high dynamics of battles with a flexible role-playing system. Work your way from a rookie on a "rusty trough" to an experienced pilot of a high-tech combat aircraft equipped with a variety of deadly gadgets. A variety of combat modes, futuristic arenas, multi-level crafting, developed trade and a social eco-system will not let you get bored for a minute!' FROM games WHERE igdb_id = 57843 ON CONFLICT (game_id, language_code) DO NOTHING;
