INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Push the Crate', 'You are looking for a logistical challenge? Look no further! Push the Crate is a 3D transport puzzle game with 300 level with varying degrees of difficulty. From kid friendly challenges to a real logistical mastermind - Push the Crate has puzzles for everyone. All you need to do is to transport the crates to their target positions and make sure you won''t get stuck.' FROM games WHERE igdb_id = 147991 ON CONFLICT (game_id, language_code) DO NOTHING;
