INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Run Jump Rabbit Turtle', 'Run Jump Rabbit Turtle is a challenging 2D platformer where you play as a rabbit and turtle. The two animals are magically combined by a Monkey Wizard in order to gather magical kiwis for him. As the player you are able to fluidly swap between the pair with simple controls defined by the game''s actual title, "Run Jump Rabbit Turtle". The game follows a humorous driven narrative, set in a dangerous cave area drawn in a retro pixel art style.' FROM games WHERE igdb_id = 117789 ON CONFLICT (game_id, language_code) DO NOTHING;
