INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('death-stranding-digital-deluxe-edition', 136160, '2019-11-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9juk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw5rq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Stranding: Digital Deluxe Edition', 'Death Stranding is an action game set in a post-apocalyptic United States. Players control Sam Porter Bridges, a courier tasked with reconnecting isolated cities via a communication network while delivering essential cargo. The gameplay blends traversal, resource management, and narrative elements, with a focus on social connectivity through asynchronous multiplayer. It is known for its unique mechanics, atmospheric world, and philosophical themes. The Digital Deluxe Edition includes: The digital full game, The following Special gold versions of in-game items once earned through gameplay: "Ludens Mask" Sunglasses, Power Skeleton, All-Terrain Skeleton (in-game item), Armor Plate (Lv. 2), A set of 10 PSN avatars featuring various characters from the game, The original soundtrack and A behind-the-scenes digital video.' FROM games WHERE igdb_id = 136160 ON CONFLICT (game_id, language_code) DO NOTHING;
