INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Green Oddities', 'Green Oddities is a Five Nights at Freddy''s fangame, a point and click horror game. Created by the Radiance Team, the game, and the entirety of the series, was intended to be a joke and not to be taken seriously. This fangame is followed by its direct sequel and final chapter, Blue Oddities. The game turned out to be a "troll game," as there is no real gameplay aside from being a 2d free-roam game.' FROM games WHERE igdb_id = 239281 ON CONFLICT (game_id, language_code) DO NOTHING;
