INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War of Power: The Last Fight', 'In 1941, shot down UFOs were found on the territory of Romania, Poland and the USSR. The captured technology of aliens helped the Allies and the Axis to strengthen their power and go far in development. Parties to the conflict are waging an aggressive war against each other, but now the outcome of the war may change at any time ...' FROM games WHERE igdb_id = 115371 ON CONFLICT (game_id, language_code) DO NOTHING;
