INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Song Beater: Quite My Tempo!', 'VR rhythm game on steroids. Beat challenging songs with your bare fists in Fit Boxing, wield variety of weapons (blades, tonfas, phasers, staff, saw) in Free Style or concentrate on text flow in Letter Hunter mode. Global and friends leaderboards, calories burnt statistics. Custom songs and videos support.' FROM games WHERE igdb_id = 119993 ON CONFLICT (game_id, language_code) DO NOTHING;
