INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kimokawaiii', 304184, '2019-08-17', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/scsk1s.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kimokawaiii', 'KIMOKAWAIII (also known as SUGOI 3, full title: KIMOKAWAIII Is My Origin, KIMOKAWAIII Always Waits And Is Intensely Interested) is the third and last entry in the SUGOI series, a series of collaborative level packs created by community members under the supervision of TehRealSalt. It contains 56 levels and features work by more than 60 different contributors, created over the months of April and May 2018 in two phases, with the first consisting of collaborative work on levels like the previous iterations (labeled KAWAIII) and a latter phase focused on the creation of custom boss fights (labeled KIMOIII), which later were merged into a single project. The level pack was initially released on August 17th, 2019, and is specially notable for bringing about the last patch of its current version of SRB2, v2.1.25, that catered to PolyObject bugs and a further expansion in the number of freeslots.' FROM games WHERE igdb_id = 304184 ON CONFLICT (game_id, language_code) DO NOTHING;
