INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cthulhu''s Catharsis', 'You are Cthulhu. This world is yours. But other eldritch horrors dare to rival Your power. Crush them. Mutate your units, raise new nations from the sea, and sacrifice humans for power. Outwit other Gods. In these strange aeons, even death may die.' FROM games WHERE igdb_id = 120008 ON CONFLICT (game_id, language_code) DO NOTHING;
