INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Orange County', 'The ever-circling specter of Elon’s children. The beige. Middle-class housing clustered like teeth in a robotic maw. The beige. The ever present hum of the sprinklers. The beige. Sometimes your skateboard feels like the only real thing in this place. With the help of your board, escape the horrors of procedurally-generated Orange County. Or try to. It’s only a matter of time.' FROM games WHERE igdb_id = 140573 ON CONFLICT (game_id, language_code) DO NOTHING;
