INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fall of April', 'The Fall of April is the fourteenth game in the Carol Reed series. Set in Sweden Carol helps her friend Andrea who suffers from temporary memory loss induced by a drug. Soon it turns out this event is not only tied to the unresolved murder of Andrea''s daughter two years before, but also to a Swedish Arctic balloon expedition in 1915. The game uses its trademark first-person view with photographs of real locations and objects in a fixed-screen slideshow style. There are puzzles to solve with items stored in an inventory near the top of the screen. A journal is used to keep track of objectives.' FROM games WHERE igdb_id = 198102 ON CONFLICT (game_id, language_code) DO NOTHING;
