INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rot', 'Rot is a short psychological horror story about obsession, rejection and self-hatred. It was developed as an experiment, to answer the question: ''can you make dread a place?''. It is inspired by titles such as P.T. and indie developer Kittyhorrorshow''s game Anatomy. It also draws inspiration from Davey Wreden''s The Beginner''s Guide. The retro, low-res aesthetic of the game is inspired by the work of Finnish indie developer 98DEMAKE, who was kind enough to get in touch during development.' FROM games WHERE igdb_id = 230560 ON CONFLICT (game_id, language_code) DO NOTHING;
