INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strike Force - War on Terror', 'Strike Force - War on Terror is a action oriented tactical shooter. Where you are a member of the Strike Force Unit. Your objective is to battle terrorism around the world! Nothing stands in your way. From vast outdoor environments to narrow bunker corridors, you are deployed to take out targets in the middle east and snowy mountains. Gear up with a modern arsenal of machine guns, assault rifles, sniper rifles and pistols and fulfill your objective.' FROM games WHERE igdb_id = 125745 ON CONFLICT (game_id, language_code) DO NOTHING;
