INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stomped', 'Stomped! combines the best parts of snowboarding and skateboarding into one premium package. Carve your way through beautiful mountain landscapes, nose-slide across stormy peaks, and kickflip over deadly chasms. Find your flow as you chain together massive combos at breakneck speed but don’t forget to stomp the landing! Stomped! will get your heart pounding as you launch over massive gaps and flip through countless beautiful locations. Let’s Shred!' FROM games WHERE igdb_id = 116541 ON CONFLICT (game_id, language_code) DO NOTHING;
