INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gravity-rider-zero', 147134, '2019-08-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57pj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbfg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Rider Zero', 'In Gravity Rider Zero, you will be climbing over obstacles, discovering trials to overcome in each level. Giant ramps, lasers, spikes, or good old gravity will try to get in your way. Enjoy a classic solo career progression system: after 3 trails you move onto the next stage. Each of them introduces a new gimmick and every planet has a unique environment! Collect dozens of unique racing vehicles with futuristic designs. Unlock new bikes by completing tasks, beating challenges or breaking track records: there’s always a new reward to look forward to! From trials bikes to ATVs, WW2 era motorbikes to space rockets, they''re all in there. You can customize your vehicle collection too. Give your motorbike a new paint job or upgrade your kart with a neon lights trail - upgrade your style! The controls in Gravity Rider Zero are simple and precise. Accelerate and tilt your bike in the right places to pass over obstacles faster. Brake in time to avoid traps. Always tilt after a jump to touch the ground earlier and gain more traction. Brake before a jump to minimize your air time, try and try again. Or, just focus on making sure you pass obstacles, don''t crash and beat the level.' FROM games WHERE igdb_id = 147134 ON CONFLICT (game_id, language_code) DO NOTHING;
