INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sairento VR: Untethered', 'Ever wanted to be a cyber ninja? A top-selling VR game and probably the best cyber ninja simulator ever, Sairento VR offers you that opportunity! Perform quadruple jumps, wall runs, power slides, back flips and even get to manipulate time. Empty lead into an enemy before spinning around to sink your blade into another. Kit yourself with katanas, firearms, bows, throwing glaives, shurikens, kunais and more - they are all at your disposal. Keep growing your experience and upgrading your skills.' FROM games WHERE igdb_id = 193695 ON CONFLICT (game_id, language_code) DO NOTHING;
