INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BRG''s Tale of the Gallant Jiraiya', 'Redemption. Romance. Adventure. All heroes have beginnings, this is the story of the legendary hero Jiraiya, Young Thunder. Jiraiya was an orphan, he quickly turn to a life of crime to survive. He believed in justice, so he stole from the rich and gave to the poor. Witness Jiraiya''s legend unfold!' FROM games WHERE igdb_id = 127502 ON CONFLICT (game_id, language_code) DO NOTHING;
