INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moai VI: Unexpected Guests', 'From vibrant jungles bursting with color, to an underwater wonderland teeming with aquatic life, to a cluster of floating islands, you''ll traverse many magical lands filled with miracles. You''ll also go toe-to-toe with awesome giants, outwit clever jellyfish and pet cute Manu-Ai to receive mana. Characters that range from the charming Posei-Don to the wicked Moko-Moko lizards will make each encounter a memorable one.' FROM games WHERE igdb_id = 117980 ON CONFLICT (game_id, language_code) DO NOTHING;
