INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu''N''Mi', 'YU''N''MI uses the device''s TrueDepth camera system to track the state of your eyes and mouth. This allows for a unique user experience - a game you can play with your face. In order for this functionality to be possible, the app requires access to your device''s camera. This access can be toggled on or off at any time in your device''s settings.INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 175745 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
