INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('legends-of-andor', 174250, '2019-01-23', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legends of Andor', 'This epic fantasy game takes you to a fantastic kingdom full of magical creatures and brave heroes. Play a warrior, sorceress, dwarf or archer, and defend the king’s castle! Pass difficult trials, defeat determined opponents and protect the land from a dark secret. Guide your group of heroes through twelve exciting legends in which new, challenging opponents and old companions await you. Choose your strategy carefully - you have only a limited number of moves to complete your quests. You can guide any legend to a successful resolution in several ways if you use your characters and their abilities to your best advantage. Delve deeper than ever before into the mystical past of the legendary kingdom and discover a previously unknown story of Andor that takes your heroes into inhospitable and dangerous realms beyond Rietland. Play the award-winning board game solo and take your group of heroes on exciting adventures anywhere, anytime. The Legends of Andor: The King’s Secret provides an easy introduction with simple rules and an extensive tutorial, and offers Andor fans and beginners alike a challenging gaming experience. The land of Andor needs your help! Can you fight off the new threat from the south?' FROM games WHERE igdb_id = 174250 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 174250 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
