INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Antrum', 'Antrum is a procedural generated dungeon where you have to collect as many relics as possible and sell them, but there is a catch, in your path you will encounter creatures that will try to defend those relics but some of them have not seen a human in a long time so they may treat you in an unexpected way.' FROM games WHERE igdb_id = 113426 ON CONFLICT (game_id, language_code) DO NOTHING;
