INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hyperide', 131423, '2019-01-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57qt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arboy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyperide', 'This game puts a modern spin on obstacle-course style vertically scrolling arcade games, and is inspired by the all-time classics. The player controls an ultra-fast spaceship on a rescue mission and needs be mindful of the oncoming space debris, as well as the power level of the ship, which is resupplied by picking up special crystals. But this is no problem for one of the speediest vessels in the galaxy! A cargo ship carrying priceless crystals was attacked by a pirate vessel. The crew abandoned the ship and is scattered throughout the void. The player answers their call for help and embarks on a journey through seven breath-taking quadrants of the void. Hyperide offers the unique opportunity to travel at warp speeds and jump through wormholes to discover the far reaches of the Universe. But the player also needs to remember that their primary mission is rescue. Apart from navigating through the debris fields and shooting oncoming enemy vessels, it’s crucial to pick up astronauts stranded in open space.' FROM games WHERE igdb_id = 131423 ON CONFLICT (game_id, language_code) DO NOTHING;
