INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Purple Chicken Spaceman', 'Earth is under attack in this quirky Shoot ''em up! And only one should-be flightless and oddly coloured fowl stands between our world and utter destruction. Join Purple Chicken as he bravely dons his fishbowl space helmet and to space, to liberate the galaxy and stop the alien invasion force before it''s too late! Do you have what it takes? Are you chicken enough?' FROM games WHERE igdb_id = 117777 ON CONFLICT (game_id, language_code) DO NOTHING;
