INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moira: Fated Twins', '《Moira: Fated Twins》是Arcanea Loft制作的大型RPG游戏。玩家将扮演一对流离他乡的兄妹，在残酷的世界中求生和成长，并在这不公平的世界中对命运做出选择。年幼的双子与家人一起生活在的和平的Arcadia山中，然而这份平静却很快被打破了。为了能找到彼此，Eleuseus和Artemisia踏上了各自的旅程。' FROM games WHERE igdb_id = 121459 ON CONFLICT (game_id, language_code) DO NOTHING;
