INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fort Sumter: Secession Crisis', 'Can you drive the Secessionist into the Fort Sumter trap that gave Lincoln his historic victory? Can you successfully use the issue of States Rights to divide Northern opinion? Fort Sumter let’s you explore this seminal moment in American history in a fast-playing, easy-to-learn game.' FROM games WHERE igdb_id = 200258 ON CONFLICT (game_id, language_code) DO NOTHING;
