INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bruken', 'Explore a large spherical world, enjoying all the jumps and puzzles etc. along the way! Overcome the oppressive forces of gravity that only get stronger as you reach the center! What even is at the center..? What is your purpose? Who knows, may aswell enjoy yourself while you''re there.' FROM games WHERE igdb_id = 116173 ON CONFLICT (game_id, language_code) DO NOTHING;
